package org.sleepwell.app;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.nio.*;import java.nio.charset.*;import java.security.*;import java.util.*;import java.util.concurrent.CancellationException;import java.util.function.BooleanSupplier;
/** Independent reviewed diary merge. No sleep records, deletes, updates or challenge owners. */
final class DiaryImport {
 static final int MAX_BYTES=4*1024*1024,MAX_ENTRIES=2000,MAX_CURRENT=10000;static final long MAX_SCAN=64L*1024*1024;
 static final class Conflict {final DiaryStore.Entry incoming,current;final String newId=UUID.randomUUID().toString();Conflict(DiaryStore.Entry incoming,DiaryStore.Entry current){this.incoming=incoming;this.current=current;}}
 static final class Review {final List<DiaryStore.Entry> fresh;final List<Conflict> conflicts;final int identical,total;final String fingerprint,source;Review(List<DiaryStore.Entry> fresh,List<Conflict> conflicts,int identical,int total,String fingerprint,String source){this.fresh=List.copyOf(fresh);this.conflicts=List.copyOf(conflicts);this.identical=identical;this.total=total;this.fingerprint=fingerprint;this.source=source;}}
 interface Commit{void begin();void committed();}
 private static void active(BooleanSupplier active){if(!active.getAsBoolean())throw new CancellationException("Diary import cancelled. No merge was committed.");}
 static Review prepare(DiaryStore store,byte[] bytes,BooleanSupplier active)throws Exception{if(bytes.length>MAX_BYTES)throw new IllegalArgumentException("Choose a diary JSON up to 4 MiB.");String text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();JSONTokener parser=new JSONTokener(text);Object value=parser.nextValue();if(!(value instanceof JSONObject)||parser.nextClean()!=0)throw new JSONException("Choose a complete diary JSON object.");JSONObject root=(JSONObject)value;if(root.length()!=2||whole(root,"diary_format")!=1)throw new JSONException("Use diary_format 1, with entries only.");JSONArray rows=root.getJSONArray("entries");if(rows.length()>MAX_ENTRIES)throw new JSONException("Use at most 2,000 diary entries per import.");List<DiaryStore.Entry> incoming=new ArrayList<>();Set<String> ids=new HashSet<>();for(int n=0;n<rows.length();n++){active(active);JSONObject row=rows.getJSONObject(n);if(row.length()!=6||!row.has("id")||!row.has("created")||!row.has("updated")||!row.has("title")||!row.has("text")||!row.has("origin"))throw new JSONException("Diary entries must contain only id, created, updated, title, text and origin; no owner.");String id=string(row,"id"),title=string(row,"title"),body=string(row,"text"),origin=string(row,"origin");try{if(!UUID.fromString(id).toString().equals(id))throw new IllegalArgumentException();}catch(IllegalArgumentException invalid){throw new JSONException("Invalid diary entry UUID.");}if(!ids.add(id))throw new JSONException("Diary entry IDs must be unique.");long created=whole(row,"created"),updated=whole(row,"updated");if(created<=0||updated<created||updated>253402300799999L||!Set.of("user","challenge").contains(origin))throw new JSONException("Invalid diary timestamps or origin.");DiaryStore.validate(title,body);incoming.add(new DiaryStore.Entry(id,created,updated,title,body,origin));}
  SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{Map<String,DiaryStore.Entry> existing=new HashMap<>();String fingerprint=fingerprint(db,ids,existing,active);List<DiaryStore.Entry> fresh=new ArrayList<>();List<Conflict> conflicts=new ArrayList<>();int identical=0;for(DiaryStore.Entry entry:incoming){DiaryStore.Entry saved=existing.get(entry.id);if(saved==null)fresh.add(entry);else if(same(saved,entry))identical++;else conflicts.add(new Conflict(entry,saved));}active(active);db.setTransactionSuccessful();return new Review(fresh,conflicts,identical,incoming.size(),fingerprint,hash(bytes));}finally{db.endTransaction();}}
 private static boolean same(DiaryStore.Entry a,DiaryStore.Entry b){return a.id.equals(b.id)&&a.created==b.created&&a.updated==b.updated&&a.title.equals(b.title)&&a.text.equals(b.text)&&a.origin.equals(b.origin);}
 private static String string(JSONObject row,String key)throws JSONException{Object value=row.get(key);if(!(value instanceof String))throw new JSONException("Diary text fields must be strings.");String text=(String)value;for(int n=0;n<text.length();n++){char ch=text.charAt(n);if(Character.isHighSurrogate(ch)){if(n+1>=text.length()||!Character.isLowSurrogate(text.charAt(++n)))throw new JSONException("Invalid Unicode diary text.");}else if(Character.isLowSurrogate(ch))throw new JSONException("Invalid Unicode diary text.");}return text;}
 private static long whole(JSONObject row,String key)throws JSONException{Object value=row.get(key);if(!(value instanceof Number)||!Double.isFinite(((Number)value).doubleValue())||((Number)value).doubleValue()!=((Number)value).longValue())throw new JSONException("Diary timestamps and version must be whole numbers.");return ((Number)value).longValue();}
 private static String hash(byte[] data)throws Exception{return NightAudioArchive.hash(MessageDigest.getInstance("SHA-256").digest(data));}
 private static void field(MessageDigest digest,String text)throws Exception{byte[] bytes=text.getBytes(StandardCharsets.UTF_8);digest.update(ByteBuffer.allocate(8).putLong(bytes.length).array());digest.update(bytes);}
 static String fingerprint(SQLiteDatabase db,Set<String> selected,Map<String,DiaryStore.Entry> matches,BooleanSupplier active)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(Cursor version=db.rawQuery("PRAGMA user_version",null)){if(!version.moveToFirst()||version.getInt(0)!=1)throw new IllegalStateException("This diary version is not supported by this import.");field(digest,"diary-schema-1");}int count=0;long bytes=0;try(Cursor cursor=db.rawQuery("SELECT id,created,updated,title,body,origin,owner FROM entries ORDER BY id",null)){while(cursor.moveToNext()){active(active);if(++count>MAX_CURRENT)throw new IllegalStateException("This diary exceeds the 10,000-entry merge limit. Existing entries are kept.");for(int col=0;col<7;col++){String text=cursor.isNull(col)?"":cursor.getString(col);bytes+=text.length()*3L+8;if(bytes>MAX_SCAN)throw new IllegalStateException("This diary exceeds the bounded merge-review limit. Existing entries are kept.");digest.update((byte)(cursor.isNull(col)?0:1));field(digest,text);}String id=cursor.getString(0);if(selected.contains(id))matches.put(id,new DiaryStore.Entry(id,cursor.getLong(1),cursor.getLong(2),cursor.getString(3),cursor.getString(4),cursor.getString(5)));}}field(digest,Integer.toString(count));return NightAudioArchive.hash(digest.digest());}
 static int merge(DiaryStore store,Review review,Set<String> asNew,BooleanSupplier active,Commit commit)throws Exception{Set<String> valid=new HashSet<>();for(Conflict conflict:review.conflicts)valid.add(conflict.incoming.id);if(!valid.containsAll(asNew))throw new IllegalArgumentException("Conflict choices changed. Review the import again.");SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();int inserted=0;try{String current=fingerprint(db,Set.of(),new HashMap<>(),active);if(!review.fingerprint.equals(current))throw new IllegalStateException("The diary changed after review. Choose the document again before merging.");for(DiaryStore.Entry entry:review.fresh){active(active);insert(db,entry,entry.id);inserted++;}for(Conflict conflict:review.conflicts){active(active);if(asNew.contains(conflict.incoming.id)){insert(db,conflict.incoming,conflict.newId);inserted++;}}active(active);commit.begin();db.setTransactionSuccessful();}finally{db.endTransaction();}commit.committed();return inserted;}
 private static void insert(SQLiteDatabase db,DiaryStore.Entry entry,String id){ContentValues values=new ContentValues();values.put("id",id);values.put("created",entry.created);values.put("updated",entry.updated);values.put("title",entry.title);values.put("body",entry.text);values.put("origin",entry.origin);values.putNull("owner");db.insertOrThrow("entries",null,values);}
 private DiaryImport(){}
}
